namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder", "Pinch of salt"],
                Steps = ["Mix dry ingredients together.", "Whisk eggs and milk, then combine with dry mix.", "Heat a buttered pan over medium heat.", "Pour batter and cook until bubbles form, then flip.", "Serve with maple syrup and fresh berries."],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple, healthy, and delicious avocado on sourdough.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Lemon juice", "Salt and pepper", "Red pepper flakes"],
                Steps = ["Toast the sourdough slices until golden.", "Mash avocado with lemon juice, salt, and pepper.", "Spread avocado on toast.", "Top with red pepper flakes."],
                AverageRating = 4.2, RatingCount = 8
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
                Description = "A creamy Italian classic with pancetta and parmesan.",
                Ingredients = ["400g spaghetti", "200g pancetta", "4 egg yolks", "1 cup parmesan", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk egg yolks with parmesan and pepper.", "Toss hot pasta with pancetta, then stir in egg mixture off heat.", "Serve immediately with extra parmesan."],
                AverageRating = 4.8, RatingCount = 20
            },
            new Recipe
            {
                Id = 4, Title = "Chicken Stir-Fry", Category = "Dinner",
                Description = "Quick and colorful weeknight stir-fry with vegetables.",
                Ingredients = ["500g chicken breast", "2 bell peppers", "1 broccoli head", "3 tbsp soy sauce", "1 tbsp sesame oil", "Ginger and garlic"],
                Steps = ["Slice chicken and vegetables.", "Heat sesame oil in a wok over high heat.", "Stir-fry chicken until golden, then set aside.", "Cook vegetables until tender-crisp.", "Return chicken, add soy sauce and ginger-garlic, toss to coat."],
                AverageRating = 4.3, RatingCount = 15
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich molten chocolate cake with a gooey center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "2 tbsp flour"],
                Steps = ["Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then add flour.", "Pour into greased ramekins.", "Bake at 220°C for 12 minutes. Center should be soft."],
                AverageRating = 4.9, RatingCount = 25
            },
            new Recipe
            {
                Id = 6, Title = "Berry Smoothie Bowl", Category = "Breakfast",
                Description = "A thick and refreshing smoothie bowl topped with granola.",
                Ingredients = ["1 cup frozen mixed berries", "1 banana", "1/2 cup yogurt", "Granola", "Chia seeds", "Fresh fruit for topping"],
                Steps = ["Blend berries, banana, and yogurt until thick.", "Pour into a bowl.", "Top with granola, chia seeds, and fresh fruit."],
                AverageRating = 4.1, RatingCount = 6
            },
            new Recipe
            {
                Id = 7, Title = "Caesar Salad", Category = "Lunch",
                Description = "Crisp romaine with homemade Caesar dressing and croutons.",
                Ingredients = ["1 head romaine lettuce", "Caesar dressing", "Croutons", "Parmesan shavings", "Grilled chicken (optional)"],
                Steps = ["Wash and chop romaine lettuce.", "Toss with Caesar dressing.", "Top with croutons and parmesan shavings.", "Add grilled chicken if desired."],
                AverageRating = 4.0, RatingCount = 10
            },
            new Recipe
            {
                Id = 8, Title = "Tomato Basil Soup", Category = "Lunch",
                Description = "Comforting homemade tomato soup with fresh basil.",
                Ingredients = ["6 large tomatoes", "1 onion", "3 cloves garlic", "Fresh basil", "Vegetable broth", "Cream"],
                Steps = ["Roast tomatoes, onion, and garlic at 200°C for 25 minutes.", "Transfer to a pot, add broth, and simmer 10 minutes.", "Blend until smooth.", "Stir in cream and fresh basil.", "Season with salt and pepper."],
                AverageRating = 4.4, RatingCount = 11
            },
            new Recipe
            {
                Id = 9, Title = "Tiramisu", Category = "Desserts",
                Description = "Classic Italian no-bake dessert with espresso and mascarpone.",
                Ingredients = ["500g mascarpone", "4 eggs", "100g sugar", "300ml strong espresso", "Ladyfinger biscuits", "Cocoa powder"],
                Steps = ["Separate eggs. Whisk yolks with sugar until pale.", "Fold in mascarpone.", "Whip egg whites to stiff peaks and fold into mixture.", "Dip ladyfingers briefly in espresso and layer in a dish.", "Alternate layers of cream and biscuits. Refrigerate 4 hours.", "Dust with cocoa powder before serving."],
                AverageRating = 4.7, RatingCount = 18
            }
        ];
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);

        var totalRatings = recipe.RatingCount + _ratings[recipeId].Count;
        var originalTotal = recipe.AverageRating * recipe.RatingCount;
        var newTotal = originalTotal + _ratings[recipeId].Sum();
        recipe.AverageRating = Math.Round(newTotal / totalRatings, 1);
        recipe.RatingCount = totalRatings;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

