+<p class="mt-2 text-muted">
+    ⭐ @CurrentRating / 5 (@RatingCount ratings)
+    @if (hasRated)
+    {
+        <span class="text-success ms-2">✓ Thanks for rating!</span>
+    }
+</p>
+
+@code {
+    [Parameter] public int RecipeId { get; set; }
+    [Parameter] public double CurrentRating { get; set; }
+    [Parameter] public int RatingCount { get; set; }
+
+    private int selectedRating;
+    private bool hasRated;
+
+    private void Rate(int stars)
+    {
+        selectedRating = stars;
+        RecipeService.AddRating(RecipeId, stars);
+        var recipe = RecipeService.GetById(RecipeId);
+        if (recipe is not null)
+        {
+            CurrentRating = recipe.AverageRating;
+            RatingCount = recipe.RatingCount;
+        }
+        hasRated = true;
+    }
+}
+

toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added to the @category category.</p>
        <a href="/category/@category" class="btn btn-primary">View in @category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <div class="mb-3">
            <label class="form-label">Recipe Title</label>
            <InputText @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect @bind-Value="category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label">Description</label>
            <InputTextArea @bind-Value="description" class="form-control" rows="2" placeholder="Brief description of the dish" />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients (one per line)</label>
            <InputTextArea @bind-Value="ingredientsText" class="form-control" rows="5" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps (one per line)</label>
            <InputTextArea @bind-Value="stepsText" class="form-control" rows="5" placeholder="Preheat oven to 180°C.&#10;Mix ingredients.&#10;Bake for 30 minutes." />
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string description = string.Empty;
    private string ingredientsText = string.Empty;
    private string stepsText = string.Empty;
    private bool submitted;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredientsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = stepsText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        RecipeService.AddRecipe(recipe);
        submitted = true;
    }

    private void Reset()
    {
        title = string.Empty;
        category = string.Empty;
        description = string.Empty;
        ingredientsText = string.Empty;
        stepsText = string.Empty;
        submitted = false;
    }
}

